"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[95956],{28453:(e,s,n)=>{n.d(s,{R:()=>i,x:()=>r});var a=n(96540);const t={},o=a.createContext(t);function i(e){const s=a.useContext(o);return a.useMemo((function(){return"function"==typeof e?e(s):{...s,...e}}),[s,e])}function r(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:i(e.components),a.createElement(o.Provider,{value:s},e.children)}},56533:(e,s,n)=>{n.d(s,{Ay:()=>r,RM:()=>o});var a=n(74848),t=n(28453);const o=[];function i(e){const s={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,t.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(s.header,{children:(0,a.jsx)(s.h1,{id:"gigolos-and-whores-the-greatest-mark-that-distinguishes-humans-from-animals",children:"Gigolos and Whores: The Greatest Mark That Distinguishes Humans from Animals!"})}),"\n",(0,a.jsxs)(s.blockquote,{children:["\n",(0,a.jsx)(s.p,{children:"2006/8/1 13:05:12"}),"\n"]}),"\n",(0,a.jsx)(s.p,{children:'First of all, animals have no gigolos or whores, because they haven\'t yet evolved to that level. The emergence of gigolos and whores is a critical milestone in biological evolution, a great marker \u2014 the greatest mark distinguishing humans from animals! So-called "rationality" is merely a product of human self-gratifying fantasy. In this regard, humans do not differ from animals in any fundamental, principled way. Moreover, this kind of purely individual functional difference is insufficient to serve as a species-level marker distinguishing humans from animals.'}),"\n",(0,a.jsx)(s.p,{children:'The basic prerequisite for the emergence of gigolos and whores is the division of labor \u2014 and specifically, the necessity of selling one\'s labor to feed oneself. This labor ultimately corresponds to various human organs, and these organs are essentially equal. All labor, in essence, is nothing more than the satisfaction of certain human needs. No amount of hypocritical vocabulary \u2014 "spiritual," "material" \u2014 can disguise the essential nature of satisfying human needs. Since human organs have no hierarchy, and human needs, which ultimately come down to organs, naturally have no hierarchy either. The so-called hierarchies of human needs are nothing but the product of intellectuals\' idle speculations born of comfort.'}),"\n",(0,a.jsx)(s.p,{children:"To play God and rank human needs as higher and lower is based on class interests. Any need related to human organs has no inherent ranking. In the end, scientifically, they can all be explained as bioelectric signals, bioenergy, and such \u2014 where is the hierarchy? Moreover, all human needs and organs ultimately share a single outcome: death, becoming ashes! In this, there is absolutely no distinction. And when humans can recognize this equal lack of distinction \u2014 that is the most critical step in humanity becoming human."}),"\n",(0,a.jsx)(s.p,{children:"Moralists who discuss sexual matters with God-like morality can only be a joke. But no joke can obscure this fact: gigolos and whores constitute humanity's oldest profession. All who opposed it have turned to ash, yet this profession endures. All morality that opposed it has turned to ash, yet this profession endures. Here, the sermonizing of moralists can only be a joke. As for linking diseases with gigolos and whores \u2014 that is an even bigger joke. The greatest causes of human death are definitely not gigolos and whores. War, natural disasters, politics, traffic accidents, environmental pollution, diet \u2014 which of these doesn't kill more than gigolos and whores? Even that so-called plague of the century \u2014 only a tiny fraction of infections occur through the sexual channel. This fact is precisely what shameless moralists deliberately conceal."}),"\n",(0,a.jsx)(s.p,{children:"Everything ultimately perishes, and gigolos and whores will be no exception. But as long as the division of human labor exists, as long as humans must sell their labor to feed themselves, as long as this selling is equal across all organs, and as long as there is no manna from heaven \u2014 then gigolos and whores will certainly exist. Because here lies an ironclad fact: this profession, with essentially zero technical barrier to entry, is humanity's most basic survival capital and bottom line. It is also the greatest mark distinguishing humans from animals, for only humans can feed themselves through the equal utilization and selling of their organs. This selling is equal \u2014 as long as one is human, one must sell. And that is the key!"})]})}function r(e={}){const{wrapper:s}={...(0,t.R)(),...e.components};return s?(0,a.jsx)(s,{...e,children:(0,a.jsx)(i,{...e})}):i(e)}},68005:(e,s,n)=>{n.r(s),n.d(s,{assets:()=>h,contentTitle:()=>l,default:()=>d,frontMatter:()=>r,metadata:()=>a,toc:()=>c});const a=JSON.parse('{"id":"essays/gigolowhore","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/essays/gigolowhore.md","sourceDirName":"essays","slug":"/essays/gigolowhore","permalink":"/essays/gigolowhore","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"gigolowhore","title":"","hide_table_of_contents":true},"sidebar":"essaysSidebar","previous":{"title":"\u201c\u4e2d\u592e\u4e00\u5957\u201d\u5f53\u7136\u53ef\u4ee5\u6210\u4e3a\u907f\u5b55\u5957\u5546\u6807\uff01 (2006/8/1 13:04:15)","permalink":"/essays/ccav"},"next":{"title":"\u963fQ\u7684\u82e6\u96be\u6c38\u8fdc\u4e0d\u80fd\u901a\u8fc7\u963fQ\u65b9\u5f0f\u89e3\u51b3 (2006/8/9 19:25:47)","permalink":"/essays/aq"}}');var t=n(74848),o=n(28453),i=n(56533);const r={id:"gigolowhore",title:"",hide_table_of_contents:!0},l=void 0,h={},c=[...i.RM];function u(e){return(0,t.jsx)(i.Ay,{})}function d(e={}){const{wrapper:s}={...(0,o.R)(),...e.components};return s?(0,t.jsx)(s,{...e,children:(0,t.jsx)(u,{...e})}):u()}}}]);